--
-- Table structure for table `STEPPER_MOTOR`
--

DROP TABLE IF EXISTS `STEPPER_MOTOR`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `STEPPER_MOTOR` (
  `ID` int unsigned NOT NULL AUTO_INCREMENT,
  `VERSION` int unsigned DEFAULT '0',
  `CREATED_TIMESTAMP` datetime DEFAULT CURRENT_TIMESTAMP,
  `UPDATED_TIMESTAMP` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `CATEGORY` varchar(32) NOT NULL COMMENT 'Category',
  `SERIES` varchar(32) DEFAULT NULL COMMENT 'Series',
  `MODEL` varchar(64) NOT NULL COMMENT 'Model',
  `NAME` varchar(64) NOT NULL COMMENT 'Name',
  `DESCRIPTION` varchar(1024) DEFAULT NULL COMMENT 'Description',
  `FRAME_SIZE` decimal(10,2) DEFAULT NULL COMMENT 'Frame Size',
  `FRAME_SIZE_UNIT` varchar(16) DEFAULT NULL COMMENT 'Frame Size Unit',
  `FRAME_SIZE_TYPE` varchar(16) DEFAULT NULL COMMENT 'Frame Size Type',
  `NEMA_SIZE` decimal(8,0) DEFAULT NULL COMMENT 'NEMA',
  `LENGTH` decimal(10,2) DEFAULT NULL COMMENT 'Motor Length',
  `LENGTH_UNIT` varchar(16) DEFAULT NULL COMMENT 'Motor Length Unit',
  `WEIGHT` decimal(10,2) DEFAULT NULL COMMENT 'Motor Weight',
  `WEIGHT_UNIT` varchar(16) DEFAULT NULL COMMENT 'Motor Weight Unit',
  `RATED_VOLTAGE` decimal(10,2) DEFAULT NULL COMMENT 'Rated Voltage',
  `RATED_VOLTAGE_UNIT` varchar(16) DEFAULT NULL COMMENT 'Rated Voltage Unit',
  `PHASE_CURRENT` decimal(10,4) DEFAULT NULL COMMENT 'Phase Current',
  `PHASE_CURRENT_UNIT` varchar(16) DEFAULT NULL COMMENT 'Phase Current Unit',
  `PHASE_RESISTANCE` decimal(10,2) DEFAULT NULL COMMENT 'Phase Resistance',
  `PHASE_RESISTANCE_UNIT` varchar(16) DEFAULT NULL COMMENT 'Phase Resistance Unit',
  `PHASE_INDUCTANCE` decimal(10,2) DEFAULT NULL COMMENT 'Phase Inductance',
  `PHASE_INDUCTANCE_UNIT` varchar(16) DEFAULT NULL COMMENT 'Phase Inductance Unit',
  `HOLDING_TORQUE` decimal(10,4) DEFAULT NULL COMMENT 'Holding Torque',
  `HOLDING_TORQUE_UNIT` varchar(16) DEFAULT NULL COMMENT 'Holding Torque Unit',
  `DETENT_TORQUE` decimal(10,4) DEFAULT NULL COMMENT 'Detent Torque',
  `DETENT_TORQUE_UNIT` varchar(16) DEFAULT NULL COMMENT 'Detent Torque Unit',
  `STEP_ANGLE` decimal(10,2) DEFAULT NULL COMMENT 'Step Angle',
  `STEP_ANGLE_UNIT` varchar(16) DEFAULT NULL COMMENT 'Step Angle Unit',
  `MAX_THRUST` decimal(10,2) DEFAULT NULL COMMENT 'Max Thrust',
  `MAX_THRUST_UNIT` varchar(16) DEFAULT NULL COMMENT 'Max Thrust Unit',
  PRIMARY KEY (`ID`),
  UNIQUE KEY `UK_STEPPER_MOTOR_MODEL` (`MODEL`),
  KEY `IX_STEPPER_MOTOR_CREATED_TIMESTAMP` (`CREATED_TIMESTAMP`),
  KEY `IX_STEPPER_MOTOR_UPDATED_TIMESTAMP` (`UPDATED_TIMESTAMP`),
  KEY `IX_STEPPER_MOTOR_CATEGORY` (`CATEGORY`),
  KEY `IX_STEPPER_MOTOR_SERIES` (`SERIES`),
  KEY `IX_STEPPER_MOTOR_FRAME_SIZE` (`FRAME_SIZE`),
  KEY `IX_STEPPER_MOTOR_NEMA_SIZE` (`NEMA_SIZE`),
  KEY `IX_STEPPER_MOTOR_LENGTH` (`LENGTH`),
  KEY `IX_STEPPER_MOTOR_WEIGHT` (`WEIGHT`),
